 if(files.length>30)throw Error(t('batchLimit'));
 const plan=KBatch.plan(files,w,C.filename),ok=plan.filter(p=>!p.error),errors=plan.filter(p=>p.error);
 if(!ok.length)throw Error(errors.map(x=>`${x.file.name}: ${x.error}`).join('\n'));
